      "components": ["R7"],
      "pins": ["R7.1", "R7.2", "U2.35", "U4.19", "U4.20"],
      "nets": ["DISP_SDA", "VCC"],
      "observed": "R7 is 10 Ω and connects DISP_SDA to VCC.",
      "expected": "R7 should be a 10 kΩ pull-up from DISP_SDA to VCC, as specified.",
      "evidence": [
        {
          "source": "netlist",
          "quote": "(comp (ref \"R7\") (value \"10\")"
        },
        {
          "source": "netlist",
          "quote": "(net (code \"3\") (name \"DISP_SDA\")"
        },
        {
          "source": "netlist",
          "quote": "(node (ref \"R7\") (pin \"2\") (pintype \"passive\"))"
        },
        {
          "source": "spec",
          "quote": "`DISP_SDA`: U2 pin 35 (`PB14`) — R7 (10 kΩ) to VCC — U4 pins 19/20 (`D1`/`D2`)"
        }
      ],
      "impact": "The display SDA line is pulled strongly toward VCC instead of through a normal pull-up. This can prevent the MCU from pulling the line low reliably and may cause excessive current when it does.",
      "confidence": 0.99
    }
  ],
  "summary": "R7 is specified as a 10 kΩ display SDA pull-up, but the netlist gives it as 10 Ω. This substantially over-strength pull-up can impair or prevent display I2C communication."
}

